 const raw=t.reduce((n,v,i)=>n+Math.max(0,Number(v)||0)*[.003,.002,.0025,.004,.004][i],0),production=120*Math.log1p(raw/100);
 const mvp=count(h,'MVP'),fmvp=count(h,'FMVP'),rings=count(h,'总冠军'),core=Math.min(rings,fmvp);
 const honors=24*Math.pow(mvp,.35)+30*Math.pow(fmvp,.4)+7*Math.sqrt(rings)+24*Math.log1p(core)+6*Math.pow(count(h,'DPOY'),.4)+7*Math.log1p(count(h,'最佳阵容一阵')*3+count(h,'最佳阵容二阵')*1.5+count(h,'最佳阵容三阵')*.75)+2.5*Math.log1p(count(h,'最佳防守一阵')+count(h,'最佳防守二阵')*.5)+2*Math.log1p(count(h,'全明星'));
