function promise(m){const s=m.season,plans=window.__v128Debug.plans;
 if(s.goal)return '<div class="v130-summary"><small>赛季目标 · 本季锁定</small><h3>'+e(s.goal.title)+'</h3><p>'+e(s.goal.desc)+'</p><span>当前打法：'+e(plans[s.plan]?.title||'未定')+' · '+(s.settled?(s.success?'已完成':'未完成'):'进行中')+'</span></div>'
 + '<p class="v130-note">打法策略可以在赛季中随时调整，下一场生效。生涯已完成赛季目标 '+ (Number(m.reputation)||0) +' 个。</p>'
 + '<div class="v130-step">打法策略 <span>赛中可调整</span></div><div class="v130-options">'+Object.keys(plans).filter(k=>k!=='mentor'||s.phase==='veteran').map(k=>chooseCard(k,plans[k].title,plans[k].desc,k===s.plan,"v130ChangePlan('"+k+"')")).join('')+'</div>'
 + '<p class="v130-note">点击即切换，下一场生效。</p>';
 const goal=ui.v130Goal&&s.options.some(x=>x.id===ui.v130Goal)?ui.v130Goal:s.options[0]?.id;ui.v130Goal=goal;
 const plan=ui.v130Plan&&plans[ui.v130Plan]&&(ui.v130Plan!=='mentor'||s.phase==='veteran')?ui.v130Plan:Object.keys(plans).filter(k=>k!=='mentor'||s.phase==='veteran')[0];ui.v130Plan=plan;
 return '<p class="v130-intro">'+e(s.intro)+'</p><div class="v130-step">01 <span>赛季目标（锁定后不可更改）</span></div><div class="v130-options">'+s.options.map(g=>chooseCard(g.id,g.title,g.desc,g.id===goal,"v130Goal('"+g.id+"')")).join('')+'</div><div class="v130-step">02 <span>初始打法（赛季中可调整）</span></div><div class="v130-options">'+Object.keys(plans).filter(k=>k!=='mentor'||s.phase==='veteran').map(k=>chooseCard(k,plans[k].title,plans[k].desc,k===plan,"v130Plan('"+k+"')")).join('')+'</div><p class="v130-note">锁定后目标不可更改；打法可随时调整。</p>';
}
function historyBody(){const data=history();if(!data)return '';const {rows,h,g}=data;const nearby=g.rows.slice(Math.max(0,g.rank-3),Math.min(g.rows.length,g.rank+2));return '<div class="v130-goat"><small>综合历史地位 · 游戏评价</small><strong><em>#</em>'+g.rank.toLocaleString()+'</strong><span>共 '+g.rows.length.toLocaleString()+' 位历史球员</span><div>'+movement(h.goatLast)+' · 最新比赛 / 荣誉结算</div><p>本季累计 · '+movement(h.goatBase-g.rank)+'</p></div><div class="v130-breakdown"><span>生涯表现<b>'+g.own.production.toFixed(1)+'</b></span><span>巅峰表现<b>'+g.own.peak.toFixed(1)+'</b></span><span>荣誉与冠军<b>'+g.own.honors.toFixed(1)+'</b></span></div><div class="v130-step">与你相邻的名字 <span>总历史评价分 '+g.own.total.toFixed(1)+'</span></div><div class="v130-nearby">'+nearby.map(x=>'<div class="'+(x.self?'is-self':'')+'"><b>#'+(g.rows.indexOf(x)+1)+'</b><span>'+e(x.name)+(x.self?' · 你':'')+'</span><strong>'+x.total.toFixed(1)+'</strong></div>').join('')+'</div><details class="v130-rule"><summary>历史地位怎么算？</summary><p>生涯累计数据采用递减收益；重复荣誉也递减，MVP 连续累积的收益进一步递减；FMVP和作为总决赛核心夺冠的履历更有分量，跟随球队夺冠与带队夺冠分别计分。最佳阵容、防阵和全明星采用对数递减，不重复计算阵容总次数。巅峰按至少50场的赛季计算，最高八季按18%、18%、18%、18%、18%、12%、10%、8%累积，单季爆发不能替代长期统治；得分、篮板、助攻、抢断、盖帽分别限制至40、18、15、4、5后加权。荣誉分随生涯厚度逐步兑现：15季以内按20%＋80%×（赛季数÷15）的四次方计入，之后完整计入。玩家与历史参照使用相同公式，没有年龄锁定。</p><p>游戏自定评价体系，并非官方排名。历史球员按本地生涯与荣誉快照作参照，部分最新或早期记录不完整，缺失项不额外加分。参照含 '+g.rows.length.toLocaleString()+' 人，不声称完整5200人。玩家替换自己的真实生涯记录。</p></details><details class="v130-rule"><summary>查看五项生涯数据历史排名</summary><div class="v130-history">'+rows.map((r,i)=>'<article><small>'+labels[r.key]+'</small><strong><em>#</em>'+r.rank.toLocaleString()+'</strong><b>'+r.total.toLocaleString()+' <span>生涯累计</span></b><div class="v130-change">最新比赛 · '+movement(h.last[i])+'</div><p>本季累计 · '+movement(h.base[i]-r.rank)+'</p></article>').join('')+'</div></details>'}
function strip(){const m=arc();if(!m)return '';const d=history(),s=m.season,plans=window.__v128Debug.plans;return '<div class="v130-strip"><button onclick="v130Open(\''+'promise'+'\')"><small>赛季目标 · 本季锁定</small><b>'+e(s.goal?s.goal.title:'这个赛季想怎么打')+'</b><span>'+ (s.goal?'本季不可更改':'先选目标') +'</span></button><button onclick="v130Open(\''+'promise'+'\')"><small>打法策略 · 可调整</small><b>'+e(plans[s.plan]?.title||'未选择')+'</b><span>赛中可切换 →</span></button><button onclick="v130Open(\'history\')" class="v130-strip-wide"><small>实时历史位置</small><b>综合 #'+d.g.rank.toLocaleString()+'</b><span>'+ (d.h.goatLast>0?'↑ '+d.h.goatLast+' 位':'查看变化 →')+'</span></button></div>'}
