window.v141Continue=function(expected){const m=D.ensure(),f=m&&window.v141Flow(m);if(!ui.v133Open||!f||career.stage!=='offseason'||f.complete||f.step!==expected||!ready(m,f))return false;cancel();if(f.step===0&&D.applyPlan)D.applyPlan(m);if(f.step===3){f.complete=true;ui.v133Open=false}else f.step++;ui.v129Tab=['plan','market','draft','roster'][f.step];save();render();return true};
window.v141SkipMarket=function(){const m=D.ensure(),f=m&&window.v141Flow(m);if(!ui.v133Open||!f||f.step!==1||f.complete||D.off(m).attempted)return;f.marketSkipped=true;save();render()};
// Retain the old callable name without permitting backward/forward navigation.
window.v133Tab=function(){return false};
const previousNextSeason=nextSeason;nextSeason=function(){if(career?.stage==='offseason'&&!flow()?.complete){v133Open();return false}return previousNextSeason.apply(this,arguments)};
function reveal(){const m=D.ensure();if(!ui.v133Open||career?.stage!=='offseason'||busy||flow()?.step!==2||flow()?.complete||D.makeDraft(m).done)return;busy=true;origin=career;const current=++token;render();timer=setTimeout(function(){timer=null;if(current!==token||career!==origin||!ui.v133Open||career.stage!=='offseason'){cancel();return}D.draftStep(m);busy=false;if(D.makeDraft(m).done)watch=false;save();render();if(watch){timer=setTimeout(()=>{timer=null;if(current===token)reveal()},900)}},window.matchMedia?.('(prefers-reduced-motion: reduce)').matches?100:1400)}
window.v133Next=function(){watch=false;reveal()};window.v133Watch=function(){if(flow()?.step!==2||flow()?.complete)return;watch=true;reveal()};window.v133Pause=function(){cancel();render()};window.v133Skip=function(){if(!ui.v133Open||flow()?.step!==2||flow()?.complete)return;cancel();v129Draft(true)};
const prevRender=render;render=function(){if(career?.stage==='offseason'&&ui.screen==='career'&&!flow()?.complete){stopSim();ui.v130Popup=null;if(!ui.v133Open){ui.v133Open=true;save()}}if(!career||career.stage!=='offseason'){cancel();ui.v133Open=false}const rv=prevRender.apply(this,arguments);document.querySelector?.('.v133-overlay')?.remove();if(ui.v133Open&&ui.screen==='career'&&career?.stage==='offseason'&&!ui.modal&&!ui.storyEvent){document.getElementById('app')?.insertAdjacentHTML('beforeend',body());document.body.classList.add('v133-dialog-open')}else{document.body.classList.remove('v133-dialog-open');if(busy||watch)cancel()}return rv};
document.addEventListener('keydown',function(event){const dialog=document.querySelector('.v133-dialog');if(!dialog)return;if(event.key==='Escape'){event.preventDefault();v133Close()}if(event.key==='Tab'){const list=Array.from(dialog.querySelectorAll('button:not([disabled]),input,summary')).filter(x=>x.getClientRects().length);const first=list[0],last=list[list.length-1];if(!first)return;if(!dialog.contains(document.activeElement)||(!event.shiftKey&&document.activeElement===last)){event.preventDefault();first.focus()}else if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus()}}});
